// Output: turn the workflow results into a report and save it to a Google Doc.
// Falls back to a local Markdown file if Google libraries/credentials are absent.
import fs from "node:fs";
import path from "node:path";
import http from "node:http";
import { config } from "../config.js";
import { latestVerdicts } from "../agents/models.js";

const DISCLAIMER =
  "This document was generated by an automated multi-agent AI workflow that uses web " +
  "search. It may contain errors, outdated figures, or AI-fabricated details. It is NOT " +
  "financial advice. Verify every figure in primary sources (SEC filings, company IR) and " +
  "consult a licensed advisor before investing.";

// ---------------------------------------------------------------------------
// Full transcript of ALL evaluated stocks. Approved companies are ranked by
// their simulation upside confidence (highest first); every rejected stock is
// also included. Plain text — used for the .txt file and the Google Doc.
// ---------------------------------------------------------------------------
export function buildReport(results) {
  const now = new Date().toISOString().slice(0, 16).replace("T", " ");
  const lines = [];
  lines.push(config.GOOGLE_DOC_TITLE);
  lines.push(`Generated: ${now}`);
  lines.push("");
  lines.push("DISCLAIMER: " + DISCLAIMER);
  lines.push("");

  // Flatten every review and tag it with its field.
  const all = [];
  for (const [field, reviews] of Object.entries(results))
    for (const r of reviews) all.push({ field, r });

  const approved = all.filter((x) => x.r.finalStatus === "APPROVED");
  const rejected = all.filter((x) => x.r.finalStatus !== "APPROVED");

  // Rank approved by simulation upside confidence (no sim -> sorts last), and
  // rejected by how close they came (critic approvals) so near-misses lead.
  const score = (x) => (x.r.simulation ? x.r.simulation.netUpside : -1);
  approved.sort((a, b) => score(b) - score(a));
  rejected.sort((a, b) => (b.r.approvals ?? 0) - (a.r.approvals ?? 0));

  lines.push(
    `SUMMARY: ${approved.length} approved, ${rejected.length} not approved, ` +
      `across ${Object.keys(results).length} field(s).`
  );
  if (approved.length === 0 && rejected.length > 0) {
    lines.push("");
    lines.push(
      `RESULT: none of the ${rejected.length} candidates cleared every gate this run. ` +
        "That is the finding — the gauntlet is strict by design (8 of 9 critics, " +
        "non-negative news, simulation confidence), and a documented \"nothing passed\" " +
        "protects you from marginal ideas. Below is the full evaluation of every " +
        "candidate, ranked by how close it came, including exactly which critics " +
        "denied it and why — the near-misses at the top are the ones to watch."
    );
  } else {
    lines.push("Approved companies are ranked below by simulation upside confidence (highest first).");
  }
  lines.push("=".repeat(72));
  lines.push("");

  // Ranked overview.
  lines.push("APPROVED — RANKED BY SIMULATION UPSIDE CONFIDENCE");
  lines.push("-".repeat(72));
  if (approved.length === 0) {
    lines.push("  (no stocks cleared the critic panel)");
  } else {
    approved.forEach((x, i) => {
      const pct = x.r.simulation ? `${x.r.simulation.netUpside}%` : "n/a";
      const nCritics = latestVerdicts(x.r).length;
      lines.push(
        `  ${String(i + 1).padStart(2)}. ${x.r.stock.ticker.padEnd(6)} ` +
          `${pct.padStart(4)}  [${x.field}]  ${x.r.stock.company}  (${x.r.approvals}/${nCritics} critics)`
      );
    });
  }
  lines.push("");
  lines.push("=".repeat(72));

  // Full detail for each approved stock, in ranked order.
  lines.push("");
  lines.push("APPROVED — FULL DETAIL (ranked)");
  if (approved.length === 0) lines.push("  (none)");
  for (const x of approved) {
    lines.push("");
    renderStockDetail(lines, x.field, x.r, true);
  }

  // Every rejected stock, with reasons, ranked by how close it came.
  lines.push("");
  lines.push("=".repeat(72));
  lines.push("NOT APPROVED — FULL DETAIL (ranked by how close each came to passing)");
  if (rejected.length === 0) lines.push("  (none)");
  for (const x of rejected) {
    lines.push("");
    renderStockDetail(lines, x.field, x.r, false);
  }

  return lines.join("\n");
}

function renderStockDetail(lines, field, r, isApproved) {
  const s = r.stock;
  const lv = latestVerdicts(r);
  const head = isApproved
    ? `${s.ticker} — ${s.company}  |  ${r.simulation ? r.simulation.netUpside + "% upside confidence" : "no simulation"}` +
      `  |  ${field}  |  ${r.approvals}/${lv.length} critics`
    : `${s.ticker} — ${s.company}  |  ${field}  |  NOT APPROVED`;
  lines.push(head);
  lines.push("-".repeat(Math.min(head.length, 72)));
  if (r.rejectReason) lines.push(`  Reason: ${r.rejectReason}`);
  lines.push(`  Proposed by: ${s.proposedBy}`);
  if (s.thesis) lines.push(`  Thesis: ${s.thesis}`);
  if (s.catalysts.length) {
    lines.push("  Catalysts:");
    for (const c of s.catalysts) lines.push(`    - ${c}`);
  }
  if (s.articles.length) {
    lines.push("  Sources:");
    for (const a of s.articles) lines.push(`    - ${a.title}: ${a.url}`);
  }
  lines.push("  Critic verdicts:");
  for (const v of lv) lines.push(`    [${v.approved ? "APPROVED" : "DENIED"}] ${v.criticName}: ${v.reasoning}`);
  if (r.debateLog.length) {
    lines.push("  Debate:");
    for (const t of r.debateLog) lines.push(`    - ${t.action.toUpperCase()} vs ${t.criticName}: ${t.argument}`);
  }
  if (r.news) {
    lines.push(`  News & sentiment — ${r.news.sentimentScore} (${r.news.label}): ${r.news.summary}`);
    if (r.news.correlation) lines.push(`    Price correlation: ${r.news.correlation}`);
    for (const a of r.news.articles || []) lines.push(`    - ${a.title}: ${a.url}`);
  }
  if (r.simulation) {
    const sim = r.simulation;
    const rr = sim.riskReward == null ? "n/a" : `${sim.riskReward}:1`;
    lines.push(
      `  Simulation — net upside confidence ${sim.netUpside}% | ` +
        `expected return ${sim.expectedReturn}% | risk/reward ${rr} ` +
        `(upside +${sim.upside}% vs downside -${sim.downside}%):`
    );
    lines.push(`    Bull P(up) ${sim.bull.probabilityIncrease}%, exp ${sim.bull.expectedReturnPct}%: ${sim.bull.reasoning}`);
    if (sim.bull.keyEvents.length) lines.push(`      Bull drivers: ${sim.bull.keyEvents.join("; ")}`);
    lines.push(`    Bear P(up) ${sim.bear.probabilityIncrease}%, exp ${sim.bear.expectedReturnPct}%: ${sim.bear.reasoning}`);
    if (sim.bear.keyEvents.length) lines.push(`      Bear drivers: ${sim.bear.keyEvents.join("; ")}`);
  }
  if (r.portfolio) {
    lines.push(`  Portfolio fit ${r.portfolio.fitScore}/100 (${r.portfolio.verdict}): ${r.portfolio.reasoning}`);
  }
}

// ---------------------------------------------------------------------------
// File writers
// ---------------------------------------------------------------------------
function timestamp() {
  const d = new Date();
  const p = (n) => String(n).padStart(2, "0");
  return (
    `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}_` +
    `${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`
  );
}

// Plain-text transcript of ALL stocks, written with CRLF so it opens cleanly
// in Windows Notepad.
export function saveText(results, filePath = null) {
  if (!filePath) filePath = `all_stocks_${timestamp()}.txt`;
  const body = buildReport(results).replace(/\r?\n/g, "\r\n");
  fs.writeFileSync(filePath, body, "utf-8");
  return path.resolve(filePath);
}

export function saveMarkdown(results, filePath = null) {
  if (!filePath) filePath = `all_stocks_${timestamp()}.md`;
  fs.writeFileSync(filePath, buildReport(results), "utf-8");
  return path.resolve(filePath);
}

// ---------------------------------------------------------------------------
// Google Docs (optional; requires the "googleapis" package + credentials.json)
// ---------------------------------------------------------------------------
async function getOAuthClient(google) {
  const SCOPES = ["https://www.googleapis.com/auth/documents"];
  const cred = JSON.parse(fs.readFileSync(config.GOOGLE_CREDENTIALS_FILE, "utf-8"));
  const conf = cred.installed || cred.web;

  // Reuse a cached token if we have one.
  if (fs.existsSync(config.GOOGLE_TOKEN_FILE)) {
    const oAuth2 = new google.auth.OAuth2(conf.client_id, conf.client_secret);
    oAuth2.setCredentials(JSON.parse(fs.readFileSync(config.GOOGLE_TOKEN_FILE, "utf-8")));
    return oAuth2;
  }

  // Otherwise run a one-time local-server OAuth flow.
  return await new Promise((resolve, reject) => {
    const server = http.createServer();
    server.listen(0, async () => {
      const redirectUri = `http://localhost:${server.address().port}`;
      const oAuth2 = new google.auth.OAuth2(conf.client_id, conf.client_secret, redirectUri);
      const authUrl = oAuth2.generateAuthUrl({ access_type: "offline", scope: SCOPES });
      console.log("\nAuthorize this app by visiting this URL in your browser:\n" + authUrl + "\n");

      server.on("request", async (req, res) => {
        try {
          const code = new URL(req.url, redirectUri).searchParams.get("code");
          if (!code) {
            res.end("Waiting for Google authorization...");
            return;
          }
          res.end("Authorization received. You can close this tab and return to the terminal.");
          server.close();
          const { tokens } = await oAuth2.getToken(code);
          oAuth2.setCredentials(tokens);
          fs.writeFileSync(config.GOOGLE_TOKEN_FILE, JSON.stringify(tokens));
          resolve(oAuth2);
        } catch (e) {
          reject(e);
        }
      });
    });
    server.on("error", reject);
  });
}

export async function saveGoogleDoc(results) {
  const { google } = await import("googleapis"); // throws if not installed
  if (!fs.existsSync(config.GOOGLE_CREDENTIALS_FILE)) {
    throw new Error(
      `Missing ${config.GOOGLE_CREDENTIALS_FILE}. Download OAuth client secrets ` +
        "(Desktop app) from Google Cloud Console with the Docs API enabled."
    );
  }
  const auth = await getOAuthClient(google);
  const docs = google.docs({ version: "v1", auth });
  const created = await docs.documents.create({ requestBody: { title: config.GOOGLE_DOC_TITLE } });
  const docId = created.data.documentId;
  await docs.documents.batchUpdate({
    documentId: docId,
    requestBody: { requests: [{ insertText: { location: { index: 1 }, text: buildReport(results) } }] },
  });
  return `https://docs.google.com/document/d/${docId}/edit`;
}

// ---------------------------------------------------------------------------
// Dispatcher
// ---------------------------------------------------------------------------
export async function save(results, mode) {
  // Always write the Notepad-friendly .txt transcript of ALL stocks.
  const txt = saveText(results);

  if (mode === "gdoc") {
    try {
      const url = await saveGoogleDoc(results);
      return `Google Doc: ${url}\nText file (open with Notepad): ${txt}`;
    } catch (e) {
      return `Google Doc failed (${e.message}).\nText file (open with Notepad): ${txt}`;
    }
  }
  if (mode === "markdown") {
    const md = saveMarkdown(results);
    return `Markdown file: ${md}\nText file (open with Notepad): ${txt}`;
  }
  return `Text file (open with Notepad): ${txt}`;
}
